import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Calendar, Check, X } from 'lucide-react';
import axios from 'axios';
import toast from 'react-hot-toast';

const DailyTracker = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [selectedDay, setSelectedDay] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (user) {
            fetchTasks();
        }
    }, [user]);

    const fetchTasks = async () => {
        try {
            const response = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(response.data);
            setLoading(false);
        } catch (error) {
            toast.error('Failed to fetch tasks');
            setLoading(false);
        }
    };

    const toggleTask = async (taskId, field) => {
        const task = tasks.find(t => t.id === taskId);
        const updatedTask = { ...task, [field]: !task[field] };
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
            toast.success('Task updated successfully');
        } catch (error) {
            toast.error('Failed to update task');
        }
    };

    const getDayTasks = (day) => {
        return tasks.filter(task => task.day === day);
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    const taskLabels = [
        { key: 'javaCompleted', label: 'Java (1.5h)' },
        { key: 'leetcodeCompleted', label: 'LeetCode (1+)' },
        { key: 'dsaCompleted', label: 'DSA/OOP (1h)' },
        { key: 'sqlCompleted', label: 'SQL/APIs/Open Source (1h)' },
        { key: 'projectCompleted', label: 'Project Dev (2-3h)' },
        { key: 'githubCompleted', label: 'GitHub/Portfolio (30m)' }
    ];

    return (
        <div className="bg-white rounded-lg shadow-lg p-6">
            <h1 className="text-2xl font-bold mb-6 flex items-center gap-2">
                <Calendar className="text-blue-600" />
                Daily Task Tracker - Month 4
            </h1>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <div className="bg-gray-50 rounded-lg p-4">
                    <h2 className="text-lg font-semibold mb-4">Calendar View</h2>
                    <div className="grid grid-cols-7 gap-2">
                        {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
                            <div key={day} className="text-center text-sm font-medium text-gray-600">
                                {day}
                            </div>
                        ))}
                        {Array.from({ length: 30 }, (_, i) => i + 1).map(day => {
                            const dayTasks = getDayTasks(day);
                            const isCompleted = dayTasks.some(t => t.overallCompleted);
                            
                            return (
                                <div
                                    key={day}
                                    className={`aspect-square rounded-lg flex items-center justify-center cursor-pointer transition-all
                                        ${isCompleted ? 'bg-green-500 text-white' : 'bg-white border-2 border-gray-200 hover:border-blue-400'}
                                        ${selectedDay === day ? 'ring-2 ring-blue-500' : ''}
                                    `}
                                    onClick={() => setSelectedDay(day)}
                                >
                                    {day}
                                </div>
                            );
                        })}
                    </div>
                </div>

                <div className="bg-gray-50 rounded-lg p-4">
                    <h2 className="text-lg font-semibold mb-4">
                        {selectedDay ? `Day ${selectedDay} Tasks` : 'Select a day'}
                    </h2>
                    
                    {selectedDay && (
                        <div className="space-y-3">
                            {taskLabels.map(({ key, label }) => {
                                const task = getDayTasks(selectedDay)[0];
                                const isCompleted = task ? task[key] : false;
                                
                                return (
                                    <div
                                        key={key}
                                        className="flex items-center justify-between bg-white p-3 rounded-lg shadow-sm"
                                    >
                                        <span className="text-gray-700">{label}</span>
                                        <button
                                            onClick={() => task && toggleTask(task.id, key)}
                                            className={`p-2 rounded-lg transition-all ${
                                                isCompleted 
                                                    ? 'bg-green-500 text-white hover:bg-green-600' 
                                                    : 'bg-gray-200 text-gray-600 hover:bg-gray-300'
                                            }`}
                                        >
                                            {isCompleted ? <Check size={20} /> : <X size={20} />}
                                        </button>
                                    </div>
                                );
                            })}

                            {getDayTasks(selectedDay).length === 0 && (
                                <div className="text-center py-8 text-gray-500">
                                    <p>No tasks for this day</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default DailyTracker;
